#include <cstdio>
#include <cmath>
#include <cstring>
#include <iostream>
#include <algorithm>
#include <vector>
#include <set>
#include <map>
#include <queue>

using namespace std;

#define sqr(x) ((x) * (x))
#define mp make_pair
#define pb push_back
#define foreach(i, a) for (__typeof(a) i = a.begin(); i != a.end(); i++)
#define FOR(i, k, n) for (int i = (k); i <= (n); i++)
#define FORD(i, k, n) for (int i = (k); i >= (n); i--)
#define REP(i, n) FOR(i, 0, (n) - 1)
#define CLEAR(a) memset(a, 0, sizeof a)
#define SZ(a) (int) (a).size()

typedef long long ll;
typedef vector<int> vi;
typedef pair<int, int> pii;

const ll INF = 1000000000000000000ll, base = 1000000007;
const int MAXN = 111111;

int main() {
	string s;
	cin >> s;
	int n = SZ(s);
	if (n == 1) {
		if (s[0] == '1')
			cout << '1';
		else
			cout << '0';
		return 0;
	}
	ll ans = 0, p = 2;
	FORD(i, n - 1, 0) {
		if (s[i] == '1')
			ans = (ans + p) % base;
		p = (p * 2) % base;
	}
	cout << ans;
	return 0;
}

